class Solution:
    def maximumPrice(self, items: List[List[int]], capacity: int) -> float:
        items.sort(key=lambda x: -x[0] / x[1])
        if sum(w for _, w in items) < capacity:
            return -1.0
        ans = 0.0
        for p, w in items:
            take = min(w, capacity)
            ans += p * take / w
            capacity -= take
            if capacity == 0:
                break
        return ans

