class Solution {
public:
    double maximumPrice(vector<vector<int>>& items, int capacity) {
        sort(items.begin(), items.end(), [](auto& a, auto& b) {
            return (double)a[0] / a[1] > (double)b[0] / b[1];
        });
        long long tot = 0;
        for (auto& it : items) tot += it[1];
        if (tot < capacity) return -1.0;
        double ans = 0;
        for (auto& it : items) {
            long long take = min((long long)it[1], (long long)capacity);
            ans += (double)it[0] * take / it[1];
            capacity -= take;
            if (!capacity) break;
        }
        return ans;
    }
};

