class Solution {
    public double maximumPrice(int[][] items, int capacity) {
        Arrays.sort(items, (a, b) -> Double.compare((double) b[0] / b[1], (double) a[0] / a[1]));
        long tot = 0;
        for (int[] it : items) tot += it[1];
        if (tot < capacity) return -1.0;
        double ans = 0;
        for (int[] it : items) {
            long take = Math.min(it[1], capacity);
            ans += (double) it[0] * take / it[1];
            capacity -= take;
            if (capacity == 0) break;
        }
        return ans;
    }
}

