var maximumPrice = function(items, capacity) {
    items.sort((a, b) => b[0] / b[1] - a[0] / a[1]);
    let tot = 0;
    for (const [, w] of items) tot += w;
    if (tot < capacity) return -1.0;
    let ans = 0;
    for (const [p, w] of items) {
        const take = Math.min(w, capacity);
        ans += p * take / w;
        capacity -= take;
        if (capacity === 0) break;
    }
    return ans;
};
